import{_ as e,C as i,c as r,o as t,j as n,G as l,b as a,a0 as s,a as d,w as o,a1 as u}from"./chunks/framework.DKRgXLPU.js";const g=JSON.parse('{"title":"Opbygning af din rutine før optagelserne","description":"","frontmatter":{},"headers":[],"relativePath":"da/education/mental-strength/pre-shot-routine.md","filePath":"da/education/mental-strength/pre-shot-routine.md"}');const k=e({name:"da/education/mental-strength/pre-shot-routine.md"},[["render",function(e,g,k,h,f,p){const m=i("AdBanner"),v=i("Mermaid"),b=i("AdInArticle");return t(),r("div",null,[g[1]||(g[1]=n("h1",{id:"opbygning-af-din-rutine-før-optagelserne",tabindex:"-1"},[d("Opbygning af din rutine før optagelserne "),n("a",{class:"header-anchor",href:"#opbygning-af-din-rutine-før-optagelserne","aria-label":'Permalink to "Opbygning af din rutine før optagelserne"'},"​")],-1)),l(m),g[2]||(g[2]=n("p",null,"Din rutine før kast er et af de mest kraftfulde værktøjer i dit mentale spil. Det er en konsekvent rækkefølge af handlinger, der forbereder dig til hvert kast og udløser din bedste præstationstilstand.",-1)),g[3]||(g[3]=n("div",{class:"tip custom-block"},[n("p",{class:"custom-block-title"},"Den store idé"),n("p",null,[n("strong",null,"Din rutine er din indgang til zonen."),d(' En konsekvent rutine før træning signalerer til din hjerne: "Det er tid til at udføre." Med gentagelse bliver det en automatisk udløser for toppræstation.')])],-1)),(t(),a(u,null,{default:o(()=>[l(v,{id:"mermaid-13",class:"mermaid",graph:"graph%20LR%0A%20%20%20%20A%5BStart%20rutine%5D%20--%3E%20B%5BHjernen%20genkender%20m%C3%B8nstre%5D%0A%20%20%20%20B%20--%3E%20C%5BAutomatisk%20tilstandsskift%5D%0A%20%20%20%20C%20--%3E%20D%5BUdf%C3%B8relsestilstand%5D%0A%20%20%20%20D%20--%3E%20E%5BPeak%20Performance%5D%0A%0A%20%20%20%20style%20A%20fill%3A%23e3f2fd%0A%20%20%20%20style%20C%20fill%3A%23e8f5e9%0A%20%20%20%20style%20D%20fill%3A%23fff4e1%0A%20%20%20%20style%20E%20fill%3A%23fff4e1%0A"})]),fallback:o(()=>[...g[0]||(g[0]=[d(" Loading... ",-1)])]),_:1})),g[4]||(g[4]=s('<h2 id="hvorfor-rutiner-virker" tabindex="-1">Hvorfor rutiner virker <a class="header-anchor" href="#hvorfor-rutiner-virker" aria-label="Permalink to &quot;Hvorfor rutiner virker&quot;">​</a></h2><h3 id="konsistens-skaber-selvtillid" tabindex="-1">Konsistens skaber selvtillid <a class="header-anchor" href="#konsistens-skaber-selvtillid" aria-label="Permalink to &quot;Konsistens skaber selvtillid&quot;">​</a></h3><p>Når du gør det samme hver gang, fjerner du variabler. Din krop ved, hvad der kommer. Dette skaber en følelse af kontrol og fortrolighed, selv i ukendte situationer.</p><h3 id="rutiners-udløsende-tilstande" tabindex="-1">Rutiners udløsende tilstande <a class="header-anchor" href="#rutiners-udløsende-tilstande" aria-label="Permalink to &quot;Rutiners udløsende tilstande&quot;">​</a></h3><p>Med gentagelse bliver din rutine knyttet til din præstationstilstand. Når rutinen startes, starter det mentale skift til udførelsestilstand automatisk.</p><h3 id="rutiner-blokerer-distraktioner" tabindex="-1">Rutiner blokerer distraktioner <a class="header-anchor" href="#rutiner-blokerer-distraktioner" aria-label="Permalink to &quot;Rutiner blokerer distraktioner&quot;">​</a></h3><p>En rutine giver dit sind noget at fokusere på. Der er ingen grund til bekymring om partituret, publikum eller hvad der kan ske.</p><h3 id="rutiner-handterer-ophidselse" tabindex="-1">Rutiner håndterer ophidselse <a class="header-anchor" href="#rutiner-handterer-ophidselse" aria-label="Permalink to &quot;Rutiner håndterer ophidselse&quot;">​</a></h3><p>En veltilrettelagt rutine hjælper med at regulere dit energiniveau - den beroliger dig, hvis du er for optaget, og fokuserer dig, hvis du er flad.</p><h2 id="elementer-i-en-effektiv-rutine" tabindex="-1">Elementer i en effektiv rutine <a class="header-anchor" href="#elementer-i-en-effektiv-rutine" aria-label="Permalink to &quot;Elementer i en effektiv rutine&quot;">​</a></h2><h3 id="fase-1-vurdering-uden-for-cirklen" tabindex="-1">Fase 1: Vurdering (uden for cirklen) <a class="header-anchor" href="#fase-1-vurdering-uden-for-cirklen" aria-label="Permalink to &quot;Fase 1: Vurdering (uden for cirklen)&quot;">​</a></h3><p>Inden du træder ind, skal du indsamle oplysninger:</p><ul><li>Læs terrænet (skråninger, forhindringer, overflade)</li><li>Vurder situationen (score, kuglepositioner)</li><li>Vælg dit mål og landingssted</li><li>Beslut dig for kasttype (point, shoot, lob, roll)</li></ul><p><strong>Det er her, tænkningen sker.</strong> Tag dig god tid her.</p><h3 id="fase-2-overgang-at-træde-ind-i-cirklen" tabindex="-1">Fase 2: Overgang (at træde ind i cirklen) <a class="header-anchor" href="#fase-2-overgang-at-træde-ind-i-cirklen" aria-label="Permalink to &quot;Fase 2: Overgang (at træde ind i cirklen)&quot;">​</a></h3><p>Skiftet fra at tænke til at handle:</p><ul><li>Fysisk handling (gå ind i cirklen på en konsekvent måde)</li><li>Mentalt signal (et ord eller en sætning, der signalerer &quot;udførelsestilstand&quot;)</li><li>Åndedræt (et bevidst åndedrag for at centrere dig selv)</li></ul><p><strong>Dette er kontakten.</strong> Analysen stopper her.</p><h3 id="fase-3-opsætning-i-cirklen" tabindex="-1">Fase 3: Opsætning (i cirklen) <a class="header-anchor" href="#fase-3-opsætning-i-cirklen" aria-label="Permalink to &quot;Fase 3: Opsætning (i cirklen)&quot;">​</a></h3><p>Forbered din krop:</p><ul><li>Konsekvent holdning (samme hver gang)</li><li>Grebstest (mærk på kuglen)</li><li>Tilpasning til målet</li><li>Fysisk udløser (en lille bevægelse, der er din)</li></ul><h3 id="fase-4-visualisering-kort" tabindex="-1">Fase 4: Visualisering (Kort) <a class="header-anchor" href="#fase-4-visualisering-kort" aria-label="Permalink to &quot;Fase 4: Visualisering (Kort)&quot;">​</a></h3><p>Se kastet, før du laver det:</p><ul><li>Forestil dig boldens bane (maksimalt 2-3 sekunder)</li><li>Føl det vellykkede kast</li><li>Forbind visuelt med din målgruppe</li></ul><h3 id="fase-5-udførelse" tabindex="-1">Fase 5: Udførelse <a class="header-anchor" href="#fase-5-udførelse" aria-label="Permalink to &quot;Fase 5: Udførelse&quot;">​</a></h3><p>Lav kastet:</p><ul><li>Eksternt fokus (kun mål)</li><li>Stol på din krop</li><li>Slip uden tøven</li><li>Følg op naturligt</li></ul>',27)),l(b),g[5]||(g[5]=s('<h2 id="opbygning-af-din-personlige-rutine" tabindex="-1">Opbygning af din personlige rutine <a class="header-anchor" href="#opbygning-af-din-personlige-rutine" aria-label="Permalink to &quot;Opbygning af din personlige rutine&quot;">​</a></h2><h3 id="trin-1-observer-hvad-du-allerede-gør" tabindex="-1">Trin 1: Observer hvad du allerede gør <a class="header-anchor" href="#trin-1-observer-hvad-du-allerede-gør" aria-label="Permalink to &quot;Trin 1: Observer hvad du allerede gør&quot;">​</a></h3><p>Du har sikkert allerede en rutine. Bemærk:</p><ul><li>Hvad gør du før gode kast?</li><li>Hvad føles naturligt for dig?</li><li>Hvad hjælper dig med at fokusere?</li></ul><h3 id="trin-2-design-din-rutine" tabindex="-1">Trin 2: Design din rutine <a class="header-anchor" href="#trin-2-design-din-rutine" aria-label="Permalink to &quot;Trin 2: Design din rutine&quot;">​</a></h3><p>Opret en sekvens, der indeholder:</p><ul><li>[ ] Vurderingsfase</li><li>[ ] Klar overgangstid</li><li>[ ] Konsekvent fysisk opsætning</li><li>[ ] Kort visualisering</li><li>[ ] Udførelsestrigger</li></ul><h3 id="trin-3-skriv-det-ned" tabindex="-1">Trin 3: Skriv det ned <a class="header-anchor" href="#trin-3-skriv-det-ned" aria-label="Permalink to &quot;Trin 3: Skriv det ned&quot;">​</a></h3><p>Vær specifik. Eksempel:</p><ol><li><strong>Vurder:</strong> Læs terrænet, vælg landingssted</li><li><strong>Overgang:</strong> Træd ind i cirklen med venstre fod først, sig &quot;tillid&quot;</li><li><strong>Opsætning:</strong> Fødder i skulderbredde, grebstest, skulderjustering</li><li><strong>Visualiser:</strong> Se stien, føl frigørelsen</li><li><strong>Udfør:</strong> Øjne på målet, kast</li></ol><h3 id="trin-4-øv-dig-religiøst" tabindex="-1">Trin 4: Øv dig religiøst <a class="header-anchor" href="#trin-4-øv-dig-religiøst" aria-label="Permalink to &quot;Trin 4: Øv dig religiøst&quot;">​</a></h3><p>Brug din rutine på HVERT kast under træning:</p><ul><li>Nemme kast</li><li>Vanskelige kast</li><li>Når du er træt</li><li>Når du er frisk</li></ul><p>Rutinen skal blive automatisk.</p><h3 id="trin-5-forfin-over-tid" tabindex="-1">Trin 5: Forfin over tid <a class="header-anchor" href="#trin-5-forfin-over-tid" aria-label="Permalink to &quot;Trin 5: Forfin over tid&quot;">​</a></h3><p>Din rutine vil udvikle sig. Læg mærke til, hvad der fungerer, og juster den. Men ændr den ikke under konkurrencer – kun mellem begivenheder.</p><h2 id="rutinemæssig-timing" tabindex="-1">Rutinemæssig timing <a class="header-anchor" href="#rutinemæssig-timing" aria-label="Permalink to &quot;Rutinemæssig timing&quot;">​</a></h2><p>Din rutine bør tage en ensartet mængde tid:</p><ul><li>For hurtigt: Du har travlt og er ikke ordentligt forberedt</li><li>For langsom: Du overtænker og mister flowet</li><li>Lige tilpas: Nok tid til at forberede sig, ikke så meget at du tænker for meget</li></ul><p><strong>Typisk tidspunkt:</strong></p><ul><li>Vurdering: 5-10 sekunder</li><li>Overgang + Opsætning: 3-5 sekunder</li><li>Visualisering + Udførelse: 3-5 sekunder</li><li><strong>I alt: 10-20 sekunder</strong></li></ul><h2 id="almindelige-rutinefejl" tabindex="-1">Almindelige rutinefejl <a class="header-anchor" href="#almindelige-rutinefejl" aria-label="Permalink to &quot;Almindelige rutinefejl&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fejl</th><th>Problem</th><th>Løsning</th></tr></thead><tbody><tr><td>Springning i praksis</td><td>Rutiner er ikke automatiske</td><td>Brug den hvert eneste kast</td></tr><tr><td>For kompliceret</td><td>Svær at huske under pres</td><td>Forenkle til det essentielle</td></tr><tr><td>Tænkning under udførelsen</td><td>Forstyrrer automatisk ydeevne</td><td>Tydelig overgangspunkt</td></tr><tr><td>Inkonsekvent timing</td><td>Skaber usikkerhed</td><td>Øv med et ensartet tempo</td></tr><tr><td>Ændring midt i konkurrencen</td><td>Introducerer tvivl</td><td>Hold fast i det, du kender</td></tr></tbody></table><h2 id="rutinemæssig-fejlfinding" tabindex="-1">Rutinemæssig fejlfinding <a class="header-anchor" href="#rutinemæssig-fejlfinding" aria-label="Permalink to &quot;Rutinemæssig fejlfinding&quot;">​</a></h2><p><strong>Hvis du har travlt:</strong></p><ul><li>Tilføj et åndedrag ved overgangen</li><li>Sænk dine opsætningsbevægelser</li><li>Pause før visualisering</li></ul><p><strong>Hvis du tænker for meget:</strong></p><ul><li>Forkort rutinen</li><li>Brug en stærkere overgangssignal</li><li>Fokuser mere eksternt</li></ul><p><strong>Hvis du er inkonsekvent:</strong></p><ul><li>Video dig selv for at tjekke</li><li>Øv rutinen uden at kaste</li><li>Få feedback fra en partner</li></ul><h2 id="eksempelrutiner" tabindex="-1">Eksempelrutiner <a class="header-anchor" href="#eksempelrutiner" aria-label="Permalink to &quot;Eksempelrutiner&quot;">​</a></h2><h3 id="simpel-rutine" tabindex="-1">Simpel rutine <a class="header-anchor" href="#simpel-rutine" aria-label="Permalink to &quot;Simpel rutine&quot;">​</a></h3><ol><li>Vælg mål</li><li>Træd ind, træk vejret</li><li>Greb, juster</li><li>Se det, kast det</li></ol><h3 id="detaljeret-rutine" tabindex="-1">Detaljeret rutine <a class="header-anchor" href="#detaljeret-rutine" aria-label="Permalink to &quot;Detaljeret rutine&quot;">​</a></h3><ol><li>Læs terrænet, vælg landingssted</li><li>Træd først venstre fod</li><li>Sig &quot;glat&quot; internt</li><li>Et åndedrag, skuldrene sænket</li><li>Fødder sat, grebskontrol</li><li>Juster skuldrene i forhold til målet</li><li>Se stien (2 sekunder)</li><li>Øjnene låses fast på målet</li><li>Kaste</li></ol><h2 id="vigtig-konklusion" tabindex="-1">Vigtig konklusion <a class="header-anchor" href="#vigtig-konklusion" aria-label="Permalink to &quot;Vigtig konklusion&quot;">​</a></h2><blockquote><p>Din rutine er dit anker. I kaos er den din konstant.</p></blockquote><p>Byg det omhyggeligt. Øv det altid. Stol fuldt og fast på det.</p>',38)),l(m)])}]]);export{g as __pageData,k as default};
